contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking all inputs that drive C.transfer
    function run(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public payable {
        require(_tos.length >= 0);

        // perform the call and capture whether it reverted
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v, _decimals) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // General rule: if the call did not revert, it must have returned true and the provided _tos was non-empty.
        // (This captures that C.transfer requires _tos.length>0 and returns true on success.)
        assert(!(reverted == false) || (ret == true && _tos.length > 0));
    }

    receive() external payable {}
}

